  function getResourceById(id) {
    if (!id || typeof id !== 'string') return null;
    return REGISTRY[id] || null;
  }

  function getAllResources() {
    return Object.values ? Object.values(REGISTRY) : Object.keys(REGISTRY).map(function(k) { return REGISTRY[k]; });
  }

  function getResourcesBySubject(subjectId) {
    return getAllResources().filter(function(r) {
      return r.subject === subjectId;
    });
  }

